import json
import re
import sys

submission = json.load(sys.stdin)
draft = submission["draft"]
headings = []
background_lines = []
for number, line in enumerate(draft.splitlines(), start=1):
    # Treat ordinary, Markdown, bold and colon section labels equally.
    label = re.sub(r"^\s*#{1,6}\s*", "", line).strip()
    label = label.strip("* ").rstrip(":").strip()
    if label.casefold() in {"overview", "use", "background"}:
        headings.append(label.casefold())
    if re.match(r"(?i)^background\s*(?::|$)", label):
        background_lines.append(number)

feedback = []
if background_lines:
    locations = ", ".join(str(number) for number in background_lines)
    feedback.append(
        f"Remove the Background section headed on line(s) {locations}, "
        "including all of its body text. Keep only Overview and Use sections."
    )
for required in ("overview", "use"):
    if required not in headings:
        feedback.append(f"Add a {required.title()} section heading and useful body text.")
if submission["subject"].casefold() not in draft.casefold():
    feedback.append(f"Mention the exact subject name: {submission['subject']}.")
if not draft.strip():
    feedback.append("Write a nonempty description.")

print(json.dumps({
    "ready": not feedback,
    "background_present": bool(background_lines),
    "background_heading_lines": background_lines,
    "headings": headings,
    "feedback": feedback,
}))

